mapper.select:
SELECT * FROM biz_clue

    is_deleted = 0

        AND (clue_name LIKE CONCAT('%', #{dto.keyword}, '%')
             OR client_company LIKE CONCAT('%', #{dto.keyword}, '%'))


        AND beike_owner LIKE CONCAT('%', #{dto.owner}, '%')


        AND clue_status = #{dto.status}


        AND clue_level = #{dto.level}


        AND (contact_date >= #{dto.dateFrom} OR create_date >= #{dto.dateFrom})


        AND (contact_date <= #{dto.dateTo} OR create_date <= #{dto.dateTo})



        AND client_circle = #{dto.clientCircle}


        AND campaign_id = #{dto.campaignId}


        AND health_status = #{dto.healthStatus}


        AND clue_level = #{dto.clueLevel}



        AND dept_belong = #{dto.deptBelong}


        AND industry = #{dto.industry}


ORDER BY create_time DESC
